local Rayfield = loadstring(game:HttpGet('https://sirius.menu/rayfield'))()

local Window = Rayfield:CreateWindow({
   Name = "AutoFarm Grace Script",
   LoadingTitle = "Thanks For WAITING for the big update!!!",
   LoadingSubtitle = "By Rewritooo, Paulovitorlo202",
   ConfigurationSaving = {
      Enabled = false,
      FolderName = nil,
      FileName = "GraceHubConfig"
   },
   Discord = {
      Enabled = false,
      Invite = "noinvite",
      RememberJoins = true
   },
   KeySystem = false,
   KeySettings = {
      Title = "AutoFarm Grace",
      Subtitle = "Key System",
      Note = "No key required",
      FileName = "GraceKey",
      SaveKey = true,
      GrabKeyFromSite = false,
      Key = {""}
   }
})

local MainTab = Window:CreateTab("Principal", 4483362458)
local FeaturesSection = MainTab:CreateSection("Funções")

MainTab:CreateButton({
   Name = "Auto Farm Kill",
   Callback = function()
      Rayfield:Notify({
         Title = "Feature Enabled",
         Content = "Auto Farm Kill has been activated.",
         Duration = 3.5,
         Image = 4483362458,
      })
      print("Auto Farm Enabled")
   end,
})

MainTab:CreateButton({
   Name = "Teleport Players",
   Callback = function()
      Rayfield:Notify({
         Title = "Feature Enabled",
         Content = "Teleport tool triggered.",
         Duration = 3.5,
         Image = 4483362458,
      })
      print("Teleport Enabled")
   end,
})

local ControlsSection = MainTab:CreateSection("Controles")

MainTab:CreateButton({
   Name = "Destroy GUI",
   Callback = function()
      Rayfield:Destroy()
   end,
})

